<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { ApiError, post, session } from '../api'
const router = useRouter(), username = ref(''), password = ref(''), confirm = ref(''), error = ref(''), saving = ref(false)
async function register() { error.value = ''; if (password.value !== confirm.value) { error.value = '两次密码输入不一致'; return } saving.value = true; try { const result = await post<{ user: typeof session.user.value }>('/auth/register', { username: username.value, password: password.value }); session.user.value = result.user; session.restored = true; router.replace('/') } catch (e) { error.value = e instanceof ApiError ? e.message : '注册失败，请稍后重试' } finally { saving.value = false } }
</script>
<template><div class="login"><section class="login-hero"><div class="login-brand">PM.</div><div class="login-copy"><h1>建立你的<br>项目工作台。</h1><div class="login-accent"/><div class="login-facts"><span>项目</span><span>风险</span><span>经营</span></div></div></section><section class="login-form-area"><form class="login-form" @submit.prevent="register"><h1>注册账户</h1><p class="subtitle">创建后，你的数据仅归属于你的账户。</p><div class="field-group"><label>用户名</label><input v-model.trim="username" class="input" autocomplete="username" minlength="3" maxlength="64" required/></div><div class="field-group"><label>密码</label><input v-model="password" type="password" class="input" autocomplete="new-password" minlength="12" required/></div><div class="field-group"><label>确认密码</label><input v-model="confirm" type="password" class="input" autocomplete="new-password" minlength="12" required/></div><p class="subtitle" style="font-size:12px;margin-top:14px">用户名可使用字母、数字、点、下划线和短横线；密码至少 12 位。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="button primary" :disabled="saving">{{saving?'注册中…':'创建账户 →'}}</button><RouterLink to="/login" class="login-link">已有账户？去登录</RouterLink></form></section></div></template>
